figure_legend_sections <- function() {
  supplied <- readLines('output/manuscript/legends-fig1-2.md',warn=FALSE)
  supplied <- supplied[!startsWith(supplied,'The independent verifier checks archive structure') & !startsWith(supplied,'For the version without')]
  supplied <- gsub('{{eTable:avatar-trace}}','the AVATAR complete trace in the supplement',supplied,fixed=TRUE)
  c(paste(supplied,collapse='\n'),
    'Figure 3 Study populations. The left branch shows all independently rated domain cells and the derived Overall populations. The right branch shows disputed cells, arm disagreements and agreed forced choices, with split choices alongside. The exclusion box identifies unsupported designs. Concordant cells give no forced-choice information. Independent ratings and signalling answers were frozen before labels were shown. No interval is applicable. D1–D5, RoB 2 domains; Overall, derived overall judgement.',
    paste('Figure 4 Forced-choice primary endpoint and sensitivity analyses. The primary population is cells where the arms disagreed and both experts chose the same label. Expert-specific and split-loss sensitivities use all arm disagreements. Exploratory strata group cells by whether ARBITER was stricter or more lenient than Unassisted. Blue circles show the ARBITER preference share; horizontal bars show 95% percentile intervals. Right labels show ARBITER count/denominator and Unassisted count. The dashed line marks equal preference. CI, confidence interval.',CI_NOTE),
    paste('Figure 5 Agreement differences and direction of disagreement. A, Paired ARBITER − Unassisted differences in exact agreement against Published, Expert 1 and Expert 2, with neutral dark markers and 95% percentile intervals. Pooled n = 510 cells; each domain n = 102; Overall n = 81 trials. Overall uses the same trials with a published Overall label in every facet. The vertical line marks zero. Independent domain and published-label comparisons are prespecified; expert-derived Overall comparisons are exploratory. B, Exploratory direction of disagreement against Published. Each bar partitions an arm’s directional disagreements into expert matches arm (medium grey), matches Published (light grey) and matches neither (near white). Segment labels are n/N. ARBITER precedes Unassisted. D1–D5, RoB 2 domains; CI, confidence interval.',CI_NOTE),
    paste('Figure 6 Domain ratings, signalling answers and rules-only recomputation. Each facet represents one independent expert. Domain-rating agreement uses all 510 cells. Collapsed signalling agreement uses only matched answers evaluable in both arms, with paired denominators in the supplementary signalling table. ARBITER uses blue circles, Unassisted orange squares, and Unassisted after rules-only recomputation orange open squares. Recalculation is exploratory and does not change the answers, so signalling rows have only two dots. Horizontal bars show 95% percentile intervals. Collapsing combines Y/PY and N/PN, with NI separate. Y, yes; PY, probably yes; N, no; PN, probably no; NI, no information; CI, confidence interval.',CI_NOTE),
    paste('eFigure 1 Absolute agreement with independent experts by domain and derived Overall. ARBITER uses blue circles, Unassisted orange squares and Published dark-grey triangles, in that order. Short horizontal ticks show expert-to-expert agreement. Each domain has 102 cells; Overall uses 102 trials for the arms and expert reliability, and 81 for Published. Missing published Overall labels are excluded. Derived Overall against experts is exploratory. Bars show 95% percentile intervals. CI, confidence interval.',CI_NOTE),
    paste('eFigure 2 Prespecified collapsed signalling-question paired differences. Rows identify the question, expert and paired denominator; only rows with at least 20 evaluable paired answers are shown. Dark circles show ARBITER − Unassisted differences with 95% percentile intervals. The complete sparse and five-level results appear in eFigure 5. Collapsing combines Y/PY and N/PN, with NI separate. CI, confidence interval.',CI_NOTE),
    paste('eFigure 3 Published-label agreement by source review. ARBITER uses blue circles and Unassisted orange squares. Marks show linearly weighted κ with 95% percentile intervals, resampling the trials within reviews. CI, confidence interval.',CI_NOTE),
    paste('eFigure 4 Prespecified domain-level signalling agreement with each independent expert. ARBITER uses blue circles and Unassisted orange squares. Facets separate experts and five-level or collapsed answers; only evaluable source-specific answers contribute. Bars show 95% percentile intervals. CI, confidence interval.',CI_NOTE),
    paste('eFigure 5 All signalling-question paired differences. Facets separate collapsed and five-level answers, including sparse and zero-answer rows. Dark circles show ARBITER − Unassisted differences with 95% percentile intervals; expert identity and paired n appear on each row. CI, confidence interval.',CI_NOTE))
}
build_figure_legends <- function() writeLines(enc2utf8(paste(figure_legend_sections(),collapse='\n\n')),'output/manuscript/figure-legends.md',useBytes=TRUE)
